/* 
	points lines in grids (planes)

	https://openprocessing.org/sketch/2151645
	#genuary22 #genuary #creativecoding #generativeart

	https://genuary.art/prompts#jan22
*/

let sze = 125;
let num, cells, bg, clrs, sw;

function setup() {
	const minWH = max(windowWidth, windowHeight);
	sze = ~~random(minWH / 20, minWH / 6)
	num = floor(minWH / sze);
	const WH = num * sze;
	num-=2; // grid offset half cell size
	createCanvas(WH, WH);
	describe("unregular grid with some combined cells with points and lines")

	pixelDensity(1)
	colorMode(HSB, 100);
	frameRate(30);
	clrs = genColors(12, 0.25);
	[bg] = clrs.splice(0, 1);
	background(bg)
	// clrs[0] = color(hue(window.color(clrs[0])), saturation(window.color(clrs[0])), brightness(window.color(clrs[0]))+32)


	randomSeed(random(day()+hour()+minute()+second()))
	initCells();
	joinCells(num);

	sw = sze * 0.1;
	strokeWeight(sw-1);
	strokeCap(ROUND);
}

function draw() {
	drawBackground(bg);
	translate(sze * 1, sze * 1)
	for (let c of cells) c.show();
	// addGrain();
  // // noLoop() removed for animation
}

// cells
function initCells() {
	cells = [];
	for (let yi = 0; yi < num; yi++) {
		for (let xi = 0; xi < num; xi++) {
			cells.push(new Cell(xi, yi, sze))
		}
	}
}
function joinCells(n = 1, tries = 10) {
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < tries; j++) {
			const c = random(cells)
			const sclX = floor(sqrt(random(num)+1));
			const sclY = floor(sqrt(random(num)+1));
			if (c.expand(sclX, sclY, cells, num)) break; // expand random cell	
		}
	}
}

// colors
function genColors(n = 2, delF = 0, space = 100) {
	arr = [];
	const HUE = ~~random(100)
	const DLT = space / n;
	for (let i = 0; i < n; i++) {
		let clr = color((HUE + i * DLT) % 100, random(35, 55), random(30, 70));
		arr.push(clr)
	}
	arr = arr.splice(0, ~~(arr.length * delF))
	return arr;
}

// interaction
function mousePressed() {
	if (mouseButton === LEFT) {
		setup();
		// joinCells();
		draw();
	}
}

// drawing
function drawBackground(bg) {
	background(bg);

	push()
	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(
		width/2, height/2, max(width, height)/3, 
		width/2, height/2, max(width, height)*.65
	);

	// Add three color stops
	gradient.addColorStop(0, clrs[0]);
	gradient.addColorStop(1, bg);

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);
	pop()
}

function addGrain() {
	push();
	stroke(0)
	const len = 5;
	for (let i = 0; i < (width + height) * 10; i++) {
		const x = random(width)
		const y = random(height)
		stroke(255, random(2, 6))
		strokeWeight(random(0.5, 2.5));
		line(x + random(-len), y, x + random(len), y)
		strokeWeight(random(0.5, 2.5));
		line(x, y + random(-4), x, y + random(4))
	}
	pop();
}

// class Cell
class Cell {
	constructor(xi, yi, sze) {
		this.xi = xi;
		this.yi = yi;
		this.sclX = 1;
		this.sclY = 1;
		this.sze = sze;
		this.clr = random(clrs);
		this.type = floor(random(1, 3)); // excluding last number
	}

	show() {
		// only draw existing cells
		if (this.sclX < 1 || this.sclY < 1) return;

		const t = millis()/1000;
		const n = noise((1 + this.xi * this.yi) * 0.32, this.xi - this.yi + this.sclX + this.sclY + this.sze, t*0.1);
		push()
		translate(this.xi * this.sze, this.yi * this.sze);
		if (n < 0.5) {
			stroke("rgba(0,0,0,0.5)");
		} else {
			stroke("rgba(255,255,255,0.5)");			
		}

		// horizontal strokes
		for (let x = 0; x < this.sclX; x++) {
			push()
			translate(x * this.sze, 0)
			point(0, 0)
			line(sw + sw, 0, this.sze - sw - sw, 0)
			// last row
			if (this.yi === num-this.sclY) {
				point(0, this.sclY*this.sze)
				line(sw + sw, this.sclY*this.sze, this.sze - sw - sw, this.sclY*this.sze)
			}
			pop()
		}

		// vertical strokes
		for (let y = 0; y < this.sclY; y++) {
			push()
			translate(0, y * this.sze)
			if (y > 0) point(0, 0)
			line(0, sw + sw, 0, this.sze - sw - sw)
			// last collumn
			if (this.xi === num-this.sclX) {
				point(this.sclX*this.sze, 0)
				line(this.sclX*this.sze, sw + sw, this.sclX*this.sze, this.sze - sw - sw)
			}
			pop()
		}

		// last cell bottom right
		if (this.xi === num-this.sclX && this.yi === num-this.sclY) {
			point(this.sclX*this.sze, this.sclY*this.sze)
		}

		pop()
	}

	// expand cell
	expand(sclX, sclY, cells, num) {
		// can cell be extended?
		// console.log(`Cell.expand() xi: ${this.xi}, yi: ${this.yi}, sclX: ${sclX}, sclY: ${sclY}, num: ${num}`)
		if ((sclX+sclY) <= 2 || this.sclX!==1 || this.sclY!==1 || this.xi + sclX > num || this.yi + sclY > num) return false;
		// console.log(` check ok`)

		// find inner cells 
		const bi = this.xi + this.yi * num; // base index
		for (let yi = 0; yi < sclY; yi++) {
			for (let xi = 0; xi < sclX; xi++) {
				const di = xi + yi * num; // delta index
				if (di && cells[bi + di].sclX !== 1) {
					return false; // dont change anything
				}
			}
		}

		// all fine, lets change scale and delete joined cells
		this.sclX = sclX;
		this.sclY = sclY;
		for (let yi = 0; yi < sclY; yi++) {
			for (let xi = 0; xi < sclX; xi++) {
				var di = xi + yi * num; // delta index
				var c = cells[bi + di];
				if (di) {
					c.sclX = 0;
					c.sclY = 0;
				}
			}
		}

		return true;
	}
}
